local WorldBossUtils = import("Game.UI.FightReady.UIWorldBoss.UIWorldBossMainDialog.WorldBossUtils")
local date = require("Frame.date")

local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

---@class WorldBossInfoDojo
local WorldBossInfoDojo = Class("WorldBossInfoDojo")

function WorldBossInfoDojo:__init()
    self.worldBossScheduleId    = ""    --- 世界Boss排期Id
    self.worldBossStartTime     = 0     --- 已经开始多少秒
    self.startDay               = ""    --- 出现时间
    self.endDay                 = ""    --- 结束时间
    self.durationTime           = 0     --- 活动持续多少秒
    self.modelId                = ""    --- 主界面入口背景
    self.NextID                 = 0     --- 下一期的ID
    self.range                  = 0     --- 关卡ID
    self.sceneId                = 0     --- 关卡场景ID
    self.remainTime             = 0     --- 距离关闭剩余多少秒
    self.isOpen                 = false --- 是否已经开放
end

function WorldBossInfoDojo:__delete()
    self.worldBossScheduleId = nil
    self.worldBossStartTime = nil
    self.startDay = nil
    self.endDay = nil
    self.durationTime = nil
    self.modelId = nil
    self.NextID = nil
    self.range = nil
    self.sceneId = nil
    self.remainTime = nil
    self.isOpen = nil
    self.openDuration = nil
end

---Update
---更新数据
---@param jsonData table
function WorldBossInfoDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = value
        end
    end
end

function WorldBossInfoDojo:StopCDTime()
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end
end

function WorldBossInfoDojo:StartTimeDown()
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end

    self._timer = CDTimerModule.GetInstance():AddCD(1, function()
        if self.worldBossStartTime > 0 then
            self.isOpen = false
        elseif self.worldBossStartTime < 0 then
            self.isOpen = true
            self.remainTime = self.durationTime - math.abs(self.worldBossStartTime)
            if self.remainTime == 0 then
                Events.Broadcast(Constants.EventNames.WorldBossEnd)
            end
        else
            Events.Broadcast(Constants.EventNames.WorldBossBegin)
        end
        self.worldBossStartTime = self.worldBossStartTime - 1
    end, CountDownTime, true, true)
end

return WorldBossInfoDojo